"use client";

import { useState } from "react";
import { Minus, Plus, RotateCcw } from "lucide-react";

const Page = () => {
  const [count, setCount] = useState(0);

  const handleIncrement = () => {
    setCount((prevCount) => prevCount + 1);
  };

  const handleDecrement = () => {
    setCount((prevCount) => prevCount - 1);
  };

  const handleReset = () => {
    setCount(0);
  };

  return (
    <main className="min-h-screen bg-slate-50 flex items-center justify-center p-5">
      <section className="w-full max-w-md rounded-3xl border border-slate-200 bg-white p-8 text-center shadow-xl shadow-slate-200/60">
        {/* Header */}
        <p className="text-sm font-semibold uppercase tracking-[0.2em] text-cyan-600">
          Counter App
        </p>

        {/* Count Display */}
        <div className="my-8 rounded-2xl border border-cyan-100 bg-cyan-50 py-8">
          <p className="text-sm font-medium text-slate-500">Current Count</p>

          <h2 className="mt-2 text-6xl font-bold text-slate-800">{count}</h2>
        </div>

        {/* Controls */}
        <div className="flex items-center justify-center gap-4">
          <button
            onClick={handleDecrement}
            aria-label="Decrement"
            className="flex size-14 items-center justify-center rounded-full border border-slate-200 bg-white text-slate-700 shadow-sm transition-all duration-200 hover:scale-105 hover:bg-slate-100 active:scale-95"
          >
            <Minus className="size-6" />
          </button>

          <button
            onClick={handleReset}
            aria-label="Reset"
            className="flex size-14 items-center justify-center rounded-full bg-cyan-500 text-white shadow-lg shadow-cyan-500/25 transition-all duration-200 hover:scale-105 hover:bg-cyan-600 active:scale-95"
          >
            <RotateCcw className="size-5" />
          </button>

          <button
            onClick={handleIncrement}
            aria-label="Increment"
            className="flex size-14 items-center justify-center rounded-full border border-slate-200 bg-white text-slate-700 shadow-sm transition-all duration-200 hover:scale-105 hover:bg-slate-100 active:scale-95"
          >
            <Plus className="size-6" />
          </button>
        </div>
      </section>
    </main>
  );
};

export default Page;

"use client";

import { useEffect, useState } from "react";
import { Pause, Play, TimerReset } from "lucide-react";

const Page = () => {
  const [time, setTime] = useState<number>(0);
  const [isRunning, setIsRunning] = useState<boolean>(false);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval> | undefined;

    if (isRunning) {
      interval = setInterval(() => {
        setTime((prevTime) => prevTime + 1);
      }, 1000);
    }

    return () => {
      clearInterval(interval);
    };
  }, [isRunning]);

  const handleStart = () => {
    setIsRunning(true);
  };

  const handleStop = () => {
    setIsRunning(false);
  };

  const handleReset = () => {
    setIsRunning(false);
    setTime(0);
  };

  const minutes = Math.floor(time / 60);
  const seconds = time % 60;

  const formattedTime = `${String(minutes).padStart(
    2,
    "0",
  )}:${String(seconds).padStart(2, "0")}`;

  return (
    <main className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
      <section className="w-full max-w-sm rounded-3xl border border-slate-200 bg-white p-8 shadow-xl shadow-slate-200/60">
        {/* Header */}
        <div className="mb-8 text-center">
          <p className="mb-2 text-sm font-semibold tracking-[0.2em] text-cyan-600 uppercase">
            Stopwatch
          </p>

          <p className="text-sm text-slate-500">
            Track your time with precision
          </p>
        </div>

        {/* Timer */}
        <div className="mb-8 flex aspect-square w-full items-center justify-center rounded-full border-10 border-cyan-100 bg-cyan-50">
          <h1 className="font-mono text-5xl font-bold tracking-tight text-slate-800 sm:text-6xl">
            {formattedTime}
          </h1>
        </div>

        {/* Controls */}
        <div className="flex justify-center gap-4">
          <button
            onClick={isRunning ? handleStop : handleStart}
            aria-label={isRunning ? "Pause stopwatch" : "Start stopwatch"}
            className="flex size-14 items-center justify-center rounded-full bg-cyan-500 text-white shadow-lg shadow-cyan-500/25 transition-all duration-200 hover:scale-105 hover:bg-cyan-600 active:scale-95"
          >
            {isRunning ? (
              <Pause className="size-6 fill-current" />
            ) : (
              <Play className="size-6 fill-current" />
            )}
          </button>

          <button
            onClick={handleReset}
            aria-label="Reset stopwatch"
            className="flex size-14 items-center justify-center rounded-full border border-slate-200 bg-white text-slate-600 shadow-sm transition-all duration-200 hover:scale-105 hover:bg-slate-100 hover:text-slate-900 active:scale-95"
          >
            <TimerReset className="size-6" />
          </button>
        </div>

        {/* Status */}
        <div className="mt-6 text-center">
          <span
            className={`inline-flex rounded-full px-4 py-1.5 text-sm font-medium ${
              isRunning
                ? "bg-green-100 text-green-700"
                : "bg-slate-100 text-slate-500"
            }`}
          >
            {isRunning ? "● Running" : "● Paused"}
          </span>
        </div>
      </section>
    </main>
  );
};

export default Page;
